/// Finds the lower‐bound insertion index `k` for `x` in the (sorted) slice `a[lo..hi]`.
/// That is, `k` is the smallest index in `[lo, hi]` such that `a[k] >= x`.
/// If all elements in `a[lo..hi]` are less than `x`, returns `hi`.
///
/// Precondition (by contract): `lo <= hi` and `hi <= a.len()`.
fn search_range_helper(a: &[i32], x: i32, lo: usize, hi: usize) -> usize {
    let mut low = lo;
    let mut high = hi;
    while low < high {
        let mid = low + (high - low) / 2;
        if a[mid] < x {
            // `x` would be inserted to the right of `mid`
            low = mid + 1;
        } else {
            // `x` could go at `mid` or to its left
            high = mid;
        }
    }
    low
}

/// Computes the lower‐bound insertion index of `x` in the first 1000 elements of `a`.
///
/// Assumes:
///   * `a.len() >= 1000`
///   * `a[0..1000]` is sorted in non‐decreasing order
///
/// Returns an index `k` in `0..=1000` such that
///   * for all `r < k`, `a[r] < x`, and
///   * for all `r >= k` (and `r < 1000`), `a[r] >= x`.
pub fn search_1000(a: &[i32], x: i32) -> usize {
    // We only consider the prefix a[0..1000].
    // By the problem's assumption, a.len() >= 1000.
    search_range_helper(a, x, 0, 1000)
}

