    #[test]
    fn test_search_range_helper() {
        let a = [1, 2, 4, 4, 5, 7, 9];
        // Search entire array:
        assert_eq!(search_range_helper(&a, 0, 0, a.len()), 0);
        assert_eq!(search_range_helper(&a, 1, 0, a.len()), 0);
        assert_eq!(search_range_helper(&a, 2, 0, a.len()), 1);
        assert_eq!(search_range_helper(&a, 3, 0, a.len()), 2);
        assert_eq!(search_range_helper(&a, 4, 0, a.len()), 2);
        assert_eq!(search_range_helper(&a, 6, 0, a.len()), 5);
        assert_eq!(search_range_helper(&a, 10, 0, a.len()), a.len());

        // Search a subrange [2..6]:
        assert_eq!(search_range_helper(&a, 1, 2, 6), 2);
        assert_eq!(search_range_helper(&a, 4, 2, 6), 2);
        assert_eq!(search_range_helper(&a, 5, 2, 6), 4);
        assert_eq!(search_range_helper(&a, 8, 2, 6), 6);
    }

    #[test]
    fn test_search_1000() {
        // Build a sorted array of length >= 1000
        let mut a: Vec<i32> = (0..1500).map(|i| (i / 2) as i32).collect();

        // For x in range, search_1000 should match a simple linear scan
        let prefix = &a[..1000];
        for x in [-1, 0, 1, 10, 100, 499, 500, 600, 750, 999, 1000, 2000] {
            let expected = prefix.iter().position(|&v| v >= x).unwrap_or(1000);
            let got = search_1000(&a, x);
            assert_eq!(got, expected, "x = {}", x);
        }
    }
